//! Kaldi fbank + kaiser_best resample parity with torchaudio.
//!
//! Reads `test/fixtures/kaldi_fbank_golden.json` (generated by
//! `test/generate_kaldi_fbank_golden.py` with torchaudio, shared with the
//! browser's `test-kaldi-fbank-golden.js`) and checks the front end used for
//! the public zs-v1 base's CAM++ embeddings. torchaudio computes in float32
//! and this port in f64, so values are compared with an absolute tolerance.
//!
//! Run: cargo test -p piper-plus --test test_kaldi_fbank_golden

use std::path::PathBuf;

use piper_plus::kaldi_fbank::{KALDI_FBANK_NUM_MEL_BINS, kaldi_fbank, resample_kaiser_best};
use serde::Deserialize;

#[derive(Deserialize)]
struct Fixture {
    signal: Signal,
    resample_cases: Vec<ResampleCase>,
    fbank_case: FbankCase,
    pipeline_case: FbankCase,
}

#[derive(Deserialize)]
struct Signal {
    dc_offset: f64,
    partials: Vec<[f64; 3]>,
}

#[derive(Deserialize)]
struct ResampleCase {
    input_rate: u32,
    seconds: f64,
    output: Vec<f32>,
}

#[derive(Deserialize)]
struct FbankCase {
    input_rate: u32,
    seconds: f64,
    frames: usize,
    values: Vec<f32>,
}

fn fixture() -> Fixture {
    let path = PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .join("../../../test/fixtures/kaldi_fbank_golden.json");
    let text =
        std::fs::read_to_string(&path).unwrap_or_else(|e| panic!("read {}: {e}", path.display()));
    serde_json::from_str(&text).expect("parse kaldi_fbank_golden.json")
}

/// Mirrors `test_signal()` in the generator: DC offset plus sines below
/// Nyquist, computed in f64 and stored as f32.
fn test_signal(signal: &Signal, sample_rate: u32, seconds: f64) -> Vec<f32> {
    let n = (f64::from(sample_rate) * seconds).round() as usize;
    (0..n)
        .map(|i| {
            let mut x = signal.dc_offset;
            for &[amplitude, freq, phase] in &signal.partials {
                if freq < f64::from(sample_rate) / 2.0 {
                    x += amplitude
                        * (2.0 * std::f64::consts::PI * freq * i as f64 / f64::from(sample_rate)
                            + phase)
                            .sin();
                }
            }
            x as f32
        })
        .collect()
}

// Tolerances cover float32 rounding in torchaudio, not algorithm changes
// (same values as test-kaldi-fbank-golden.js): the largest fbank
// differences sit in bins whose log energy is near -16, where float32 FFT
// cancellation dominates; a wrong window, mel scale or preemphasis moves
// whole frames by far more than 1e-2.
const RESAMPLE_MAX_ABS: f32 = 5e-5;
const FBANK_MAX_ABS: f32 = 1e-2;
const FBANK_MEAN_ABS: f32 = 1e-3;

fn abs_diffs(actual: &[f32], expected: &[f32]) -> (f32, f32) {
    assert_eq!(actual.len(), expected.len(), "length");
    let mut max = 0.0f32;
    let mut sum = 0.0f64;
    for (a, e) in actual.iter().zip(expected) {
        let d = (a - e).abs();
        max = max.max(d);
        sum += f64::from(d);
    }
    (max, (sum / actual.len() as f64) as f32)
}

fn assert_fbank_close(feats: &[f32], case: &FbankCase) {
    assert_eq!(
        feats.len() / KALDI_FBANK_NUM_MEL_BINS,
        case.frames,
        "frames"
    );
    let (max, mean) = abs_diffs(feats, &case.values);
    assert!(max < FBANK_MAX_ABS, "max abs diff {max}");
    assert!(mean < FBANK_MEAN_ABS, "mean abs diff {mean}");
}

#[test]
fn resample_matches_torchaudio_sinc_interp_kaiser() {
    let fx = fixture();
    assert!(!fx.resample_cases.is_empty());
    for case in &fx.resample_cases {
        let input = test_signal(&fx.signal, case.input_rate, case.seconds);
        let out = resample_kaiser_best(&input, case.input_rate, 16000);
        let (max, _) = abs_diffs(&out, &case.output);
        assert!(
            max < RESAMPLE_MAX_ABS,
            "{} Hz -> 16000 Hz: max abs diff {max}",
            case.input_rate
        );
    }
}

#[test]
fn fbank_matches_torchaudio_on_16k_signal_with_dc_offset() {
    let fx = fixture();
    let c = &fx.fbank_case;
    assert_eq!(c.input_rate, 16000);
    let feats = kaldi_fbank(&test_signal(&fx.signal, c.input_rate, c.seconds));
    assert_fbank_close(&feats, c);
}

#[test]
fn fbank_matches_torchaudio_after_resampling_48k() {
    let fx = fixture();
    let c = &fx.pipeline_case;
    let resampled = resample_kaiser_best(
        &test_signal(&fx.signal, c.input_rate, c.seconds),
        c.input_rate,
        16000,
    );
    assert_fbank_close(&kaldi_fbank(&resampled), c);
}
